const body = $input.first().json.body || $input.first().json;

function sanitizePhone(raw) {
  if (!raw) return '';
  let s = String(raw).trim();
  const match = s.match(/(?:(?:\+|00)?\d{1,4}[-.\s]?)?(?:\(?\d{2,5}\)?[-.\s]?)?\d{3,5}[-.\s]?\d{3,5}/);
  if (match) s = match[0];
  let digits = s.replace(/\D/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  if (digits.length === 11 && digits.startsWith('0')) digits = '91' + digits.slice(1);
  if (/^9191\d{10}$/.test(digits)) digits = '91' + digits.slice(4);
  if (digits.length === 10 && /^[6-9]/.test(digits)) digits = '91' + digits;
  return digits;
}

const rawPhone = body.phone_number || body.phone || body.lead_phone || '';
const phone = sanitizePhone(rawPhone);
const customerName = String(body.customer_name || body.callerName || body.name || 'Valued Guest').trim();
const companyName = String(body.company_name || 'Elite Co-Works').trim();
const visitRef = String(body.visitReference || body.booking_ref || body.reference || 'VISIT-' + Date.now().toString(36).toUpperCase()).trim();
const slotDate = String(body.slot_date || body.visitDate || body.date || '').trim();
const slotTime = String(body.slot_time || body.timeSlot || body.time || '').trim();
const locationName = String(body.locationName || 'BTM Layout 1st Stage').trim();
const hostName = String(body.hostName || 'Kavita Reddy (Centre Manager)').trim();

const isValid = phone.length >= 10 && phone.length <= 15 && Boolean(visitRef);

const payload = {
  messaging_product: 'whatsapp',
  to: phone,
  type: 'template',
  template: {
    name: 'sales_appointment_confirmed',
    language: { code: 'en' },
    components: [
      {
        type: 'header',
        parameters: [{ type: 'text', text: companyName }]
      },
      {
        type: 'body',
        parameters: [
          { type: 'text', text: customerName },
          { type: 'text', text: 'Site Tour / Walkthrough' },
          { type: 'text', text: companyName },
          { type: 'text', text: visitRef },
          { type: 'text', text: slotDate },
          { type: 'text', text: slotTime },
          { type: 'text', text: `${locationName} — Host: ${hostName}` }
        ]
      }
    ]
  }
};

return [{
  json: {
    valid: isValid,
    raw_phone: rawPhone,
    phone_number: phone,
    customer_name: customerName,
    company_name: companyName,
    visit_ref: visitRef,
    slot_date: slotDate,
    slot_time: slotTime,
    payload: payload
  }
}];
